sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {

    // Add your code here
    var medication = new MedicationUtils()

    var dosage = medication.getTotalDosage('MED0001017')
    if (dosage) {
        gs.print(dosage);
    }

    var avai = medication.isMedicationAvailable('MED0001017')
    if (avai) {
        gs.print(avai)
    } else {
        gs.print('Not found..')
    }
    gs.print("------------------------")

    var _mediDetails = medication.getMedicationByID('MED0001017')
    if (_mediDetails) {
        gs.print("Medication ID: " + _mediDetails.number)
        gs.print("Patient ID: " + _mediDetails.u_patient_id.getDisplayValue());
        gs.print("MEdication Name: " + _mediDetails.u_medication_name);
        gs.print("---------------------")
    } else {
        gs.print('Not found..')
    }

    var _mediDetailsByPatientID = medication.getMedicationsByPatientID('0214c8f093626610ec38b2ddfaba105e')
    if (_mediDetailsByPatientID) {
        while (_mediDetailsByPatientID.next()) {
            gs.print(_mediDetailsByPatientID.number)
        }
    }



})(current, previous);
